additionalExercises.referenceSolution:
#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    int *pa = &a;
    int *pb = &b;
    int tmp = *pa;
    *pa = *pb;
    *pb = tmp;
    printf("%d %d\n", a, b);
    return 0;
}

